use serde_json::{json,Value};
use std::io::{Cursor,Read,Write};
use kfc_kfc_alpha::kfc::{ooxfr::OxfXlRelations::{self,OxfXlRelations as X},ooxfw::OxfwPackage::OxfwPackage,opcw::{native::{PartRef,RelationRef},OpcwPackagePart::OpcwPackagePart}};
use ss_core::cn::wps::moss::xlsxw::util::XlsxwPackage::XlsxwPackage as P;
fn base64(s:&[u8])->String{let a=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for p in s.chunks(3){let v=((p[0]as u32)<<16)|((p.get(1).copied().unwrap_or(0)as u32)<<8)|p.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>p.len(){'='}else{a[((v>>(18-i*6))&63)as usize]as char});}}out}
fn entries(file:&std::path::Path)->Value{let mut z=zip::ZipArchive::new(Cursor::new(std::fs::read(file).unwrap())).unwrap();let mut out=vec![];for i in 0..z.len(){let mut e=z.by_index(i).unwrap();let mut b=vec![];e.read_to_end(&mut b).unwrap();out.push(json!({"name":e.name(),"method":e.compression().to_u16(),"size":e.size(),"crc":e.crc32(),"bytes":base64(&b)}));}json!(out)}
fn runtime(e:Box<dyn std::any::Any+Send>)->(String,String){let cause=e.downcast::<ss_core::java_runtime::RuntimeException::RuntimeException>().expect("original RuntimeException(IOException)");("RuntimeException".into(),kfs_kfs_app::kfs::zip::ZipErrors::javaExceptionName(&cause.0).into())}
#[test]
fn original_android_xlsxw_factories_and_stream_overloads(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/xlsxw-r0b29");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();ss_core::java_runtime::KfsZip::install();let mut packages=vec![];
    for expected in java["packages"].as_array().unwrap(){let mode=expected["mode"].as_i64().unwrap();let mask=expected["mask"].as_i64().unwrap();if mode==0{X::setXlsRelation();}else{X::setClipRelation();}let file=p.join(format!("zips/rust-{mode}-{mask}.zip"));let mut pack=OxfwPackage::OxfwPackage(file.to_str().unwrap()).unwrap();let book=P::createBookPart(&mut pack,mask&1!=0,mask&2!=0);let repeated=P::createBookPart(&mut pack,mask&1==0,mask&2==0);let same=match(&book,&repeated){(PartRef::Base(a),PartRef::Base(b))=>std::rc::Rc::ptr_eq(a,b),_=>false};let mut row=json!({"mode":mode,"mask":mask,"book":book.getPartName(),"sameBook":same});book.withBaseMut(|b|P::getOutputStream(b)).unwrap().write_all(b"<book/>").unwrap();let relses=book.getRelationships();let mut parts=vec![];
        for input in expected["parts"].as_array().unwrap(){let kind=input["kind"].as_i64().unwrap();let index=input["index"].as_i64().unwrap()as i32;let part={let mut r=relses.borrow_mut();match kind{0=>P::createCellImagesPart(&mut r),1=>P::createStylesPart(&mut r),2=>P::createStringsPart(&mut r),3=>P::createThemePart(&mut r),4=>P::createThemeOverridePart(&mut r,index),5=>P::createItems(&mut r,index),6=>P::createItemProps(&mut r,index),7=>P::createWebExtension(&mut r,index),8=>P::createPivotTable(&mut r,index),_=>panic!("kind")}};let entry=ss_core::java_runtime::KfsZip::Entry(kfs_kfs_app::kfs::zip::ZipEntry::ZipEntry::new__string("original-name".into()));let stream=part.withBaseMut(|part|match kind%4{0=>P::getOutputStream(part),1=>P::getOutputStream__2(part,Some(&entry)),2=>P::getOutputStream__3(part,Some(&entry),None),_=>P::getOutputStream__4(part,Some(&entry),None,None)});stream.unwrap().write_all(format!("part-{kind}-{index}").as_bytes()).unwrap();let error=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||part.withBaseMut(P::getOutputStream))).map_or_else(runtime,|_|("ok".into(),"none".into()));let observed=json!({"kind":kind,"index":index,"part":part.getPartName(),"entryUnchanged":entry.0.getName()=="original-name","repeat":error.0,"cause":error.1});assert_eq!(observed,*input,"mode {mode}, kind {kind}, index {index}");parts.push(observed);}
        row["parts"]=json!(parts);row["rootCount"]=json!(pack.getRelationships().borrow().size());row["bookCount"]=json!(relses.borrow().size());let mut images=vec![];for input in expected["images"].as_array().unwrap(){let t=input["input"].as_i64().unwrap()as i32;let a=P::getRelation(t);let again=P::getRelation(t);let observed=json!({"input":t,"value":{"content":a.getContentType(),"type":a.getRelsType(),"part":a.getPartName()},"same":std::ptr::eq(&*a,&*again)});assert_eq!(observed,*input);images.push(observed);}row["images"]=json!(images);pack.close().unwrap();row["entries"]=entries(&file);assert_eq!(row,*expected,"mode {mode}, mask {mask}");packages.push(row);
    }X::setXlsRelation();let mut null_streams=vec![];for i in 0..4{let mut part=OpcwPackagePart::OpcwPackagePart(None,RelationRef::Static(&*OxfXlRelations::WORKBOOK),-1);let stream=match i{0=>P::getOutputStream(&mut part),1=>P::getOutputStream__2(&mut part,None),2=>P::getOutputStream__3(&mut part,None,None),_=>P::getOutputStream__4(&mut part,None,None,None)};null_streams.push(stream.is_none());}let actual=json!({"packages":packages,"nullStreams":null_streams});assert_eq!(actual,java);std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
